var pipeline = new ResiliencePipelineBuilder<HttpResponseMessage>()
    .AddRetry(new RetryStrategyOptions<HttpResponseMessage>
    {
        ShouldHandle = new PredicateBuilder<HttpResponseMessage>()
            .Handle<HttpRequestException>()
            .HandleResult(r => r.StatusCode is HttpStatusCode.ServiceUnavailable
                                       or HttpStatusCode.TooManyRequests),
        MaxRetryAttempts = 3,
        DelayGenerator = args => new ValueTask<TimeSpan?>(
            TimeSpan.FromMilliseconds(Math.Pow(2, args.AttemptNumber) * 200))
    })
    .AddCircuitBreaker(new CircuitBreakerStrategyOptions<HttpResponseMessage>
    {
        FailureRatio = 0.5,
        SamplingDuration = TimeSpan.FromSeconds(30),
        MinimumThroughput = 10,
        BreakDuration = TimeSpan.FromSeconds(60)
    })
    .AddTimeout(TimeSpan.FromSeconds(3))
    .Build();

public async Task<TaxRate> GetTaxRateAsync(TaxQuery query, CancellationToken ct)
{
    var cacheKey = $"tax:{query.Country}:{query.PostalCode}:{query.Category}";
    var cached = await cache.GetStringAsync(cacheKey, ct);
    if (cached is not null) return JsonSerializer.Deserialize<TaxRate>(cached)!;

    try
    {
        var response = await pipeline.ExecuteAsync(
            async token => await httpClient.GetAsync($"/rate?{query}", token), ct);
        response.EnsureSuccessStatusCode();
        var rate = await response.Content.ReadFromJsonAsync<TaxRate>(ct)!;

        // Cache with a long TTL: rates change rarely and audit needs the value
        await cache.SetStringAsync(cacheKey, JsonSerializer.Serialize(rate),
            new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(24) }, ct);
        return rate;
    }
    catch (Exception ex) when (ex is BrokenCircuitException or TimeoutRejectedException)
    {
        // Degrade: use the stored rate if we have one, otherwise defer
        await queue.EnqueueAsync(new TaxCalculationDeferred(query), ct);
        throw new TaxServiceUnavailableException(query, ex);
    }
}
